#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<int> arr(n);
    for (int& x : arr) {
        cin >> x;
        --x;
        if (x < 0 || x >= n) {
            cout << -1 << '\n';
            return 0;
        }
    }

    vector<bool> visited(n, false);
    vector<int> ans;

    for (int i = 0; i < n; ++i) {
        if (visited[i]) continue;

        int current = i;
        int length = 0;

        while (!visited[current]) {
            visited[current] = true;
            ++length;
            current = arr[current];
        }

        if (current != i) {
            cout << -1 << '\n';
            return 0;
        }

        if (length % 2 == 0) length /= 2;
        ans.push_back(length);
    }

    if (ans.empty()) {
        cout << -1 << '\n';
        return 0;
    }

    sort(ans.begin(), ans.end());
    int result = ans.back();

    for (int x : ans) {
        if (result % x != 0) {
            cout << -1 << '\n';
            return 0;
        }
    }

    cout << result << '\n';
    return 0;
}

