int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    if (n <= 0) {
        cout << -1 << '\n';
        return 0;
    }

    vector<int> arr(n + 1);
    vector<bool> visited(n + 1, false);

    for (int i = 1; i <= n; ++i) {
        cin >> arr[i];
        if (arr[i] < 1 || arr[i] > n) {
            cout << -1 << '\n';
            return 0;
        }
    }

    vector<int> ans;

    for (int i = 1; i <= n; ++i) {
        if (visited[i]) {
            continue;
        }

        int current = i;
        int length = 0;

        while (!visited[current]) {
            visited[current] = true;
            ++length;
            current = arr[current];
        }

        if (current != i) {
            cout << -1 << '\n';
            return 0;
        }

        if (length % 2 == 0) {
            length /= 2;
        }

        ans.push_back(length);
    }

    sort(ans.begin(), ans.end());

    for (int i = static_cast<int>(ans.size()) - 2; i >= 0; --i) {
        if (ans.back() % ans[i] != 0) {
            cout << -1 << '\n';
            return 0;
        }
    }

    cout << ans.back() << '\n';
    return 0;
}

